import{_ as l,l as o,o as t,c as i,v as e,p as d,x as r,d as h,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"反向传播一行一层","description":"","frontmatter":{"title":"反向传播一行一层","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/backprop-layerwise.md","filePath":"llm/backprop-layerwise.md","lastUpdated":1789023840000}'),n={name:"llm/backprop-layerwise.md"};function E(_,a,c,B,f,u){const m=o("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="反向传播一行一层" tabindex="-1">反向传播一行一层 <a class="header-anchor" href="#反向传播一行一层" aria-label="Permalink to &quot;反向传播一行一层&quot;">​</a></h1><div class="epigraph"><p>每一层只做一件事：把上游送来的输出梯度，乘上本层的局部导数，变成输入梯度与权重梯度。</p><footer>—— 据 Rumelhart, Hinton &amp; Williams, Nature 1986；Goodfellow et al., Deep Learning, 2016 整理</footer></div><p><a href="/llm/chain-rule-graph">链式法则与计算图</a>给出逆序乘局部 Jacobian 的程序。本课不重画整图。缺口是：把「层」当成注册好的算子，列出线性层与逐元素非线性在矩阵记号下的一行规则，使后课谈到 MLP、残差时不必每次从标量链式法则推起。自动微分的两种模式、梯度消失，分别是后两课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>图上的结点可以细到一次加法。训练时人思考的单位是层：\\(y=Wx\\)、\\(h=\\sigma(y)\\)、再接到损失。若每改一种层都回到 \\(\\partial w_i/\\partial x_j\\) 的双重求和，笔记会比代码还长。缺口是把常见层的正向与反向并排写成形状合法的矩阵乘与逐元素乘，并指出哪些中间量必须缓存。</p><p>以线性层为例。正向 \\(Y=XW^\\top\\)，形状 \\((B,d_{\\mathrm{out}})=(B,d_{\\mathrm{in}})\\times(d_{\\mathrm{in}},d_{\\mathrm{out}})\\)。上游 \\(\\mathrm{d}Y\\) 与 \\(Y\\) 同形。则 \\(\\mathrm{d}X=\\mathrm{d}Y\\,W\\)，\\(\\mathrm{d}W=\\mathrm{d}Y^\\top X\\)。这不是新的链式法则，只是把 Jacobian 乘积收成两次 GEMM。激活函数 \\(h=\\sigma(y)\\) 的反向是 \\(\\mathrm{d}y=\\mathrm{d}h\\odot\\sigma&#39;(y)\\)，缓存 \\(y\\) 或 \\(\\sigma&#39;(y)\\)。</p><h3 id="层的反向不是「把正向公式里的符号对调」" tabindex="-1">层的反向不是「把正向公式里的符号对调」 <a class="header-anchor" href="#层的反向不是「把正向公式里的符号对调」" aria-label="Permalink to &quot;层的反向不是「把正向公式里的符号对调」&quot;">​</a></h3><p>\\(Y=XW^\\top\\) 并不意味 \\(\\mathrm{d}X=Y\\,\\mathrm{d}W\\) 之类随意排列。每一条规则都来自 \\(\\mathrm{d}L=\\langle\\mathrm{d}Y,\\mathrm{d}Y_{\\mathrm{from}\\,X,W}\\rangle\\) 的配对本。写错转置是最常见的实现错误，形状检查会立刻抓住——这正是第一课形状纪律的用处。不要用「反向就是正向的逆矩阵」来记：ReLU 没有逆，线性层的 \\(W\\) 也几乎不可逆。</p><p><span class="marginnote">批维 \\(B\\) 在 \\(\\mathrm{d}W\\) 上是求和：每个样本贡献一份外积，加在同一张 \\(W\\) 上。这与「\\(W\\) 被所有样本共享」是同一件事的反向说法。序列维同样求和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对堆叠 \\(h^{(\\ell+1)}=\\sigma(W^{(\\ell)}h^{(\\ell)})\\)（偏置暂略），反向从最后一层的 \\(\\mathrm{d}h^{(L)}\\)（对交叉熵接 softmax，即 \\(p-y\\)）开始：</p><ol><li>若本层有激活，\\(\\mathrm{d}y\\leftarrow\\mathrm{d}h\\odot\\sigma&#39;(y)\\)；</li><li>\\(\\mathrm{d}W\\leftarrow\\mathrm{d}y\\,h_{\\mathrm{prev}}^\\top\\)（按批求和写成矩阵乘）；</li><li>\\(\\mathrm{d}h_{\\mathrm{prev}}\\leftarrow W^\\top\\mathrm{d}y\\)；</li><li>进入更浅一层。</li></ol><p>一行一层，直到输入或嵌入表。嵌入表的反向是 scatter：只把 \\(\\mathrm{d}h\\) 加到被查中的行上，与<a href="/llm/embed-as-lookup-motive">嵌入作为查找</a>将要强调的稀疏更新一致；本课先在稠密线性层上把形状写对。</p>',13)),(t(),d(p,null,{default:r(()=>[s(m,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22%E4%B8%8A%E6%B8%B8%20dH%22%5D%20--%3E%20ACT%5B%22%E9%80%90%E5%85%83%E7%B4%A0%E4%B9%98%E6%BF%80%E6%B4%BB%E5%AF%BC%E6%95%B0%22%5D%0A%20%20ACT%20--%3E%20DY%5B%22dY%22%5D%0A%20%20DY%20--%3E%20DW%5B%22dW%20%E7%AD%89%E4%BA%8E%20dY%20%E4%B9%98%E8%BE%93%E5%85%A5%E8%BD%AC%E7%BD%AE%22%5D%0A%20%20DY%20--%3E%20DX%5B%22dX%20%E7%AD%89%E4%BA%8E%20W%20%E8%BD%AC%E7%BD%AE%E4%B9%98%20dY%22%5D%0A%20%20DX%20--%3E%20PREV%5B%22%E9%80%81%E5%88%B0%E6%9B%B4%E6%B5%85%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把反向写成层规则之后，实现可以融合：线性+激活+损失不必三次写全局内存。更重要的是诊断：某一层 \\(\\mathrm{d}W\\) 的范数接近 \\(0\\)，问题在该层局部导数（饱和激活、过大的 softmax），而不是「整网不会求导」。某一层 \\(\\mathrm{d}W\\) 爆炸，问题在局部增益连乘，那是<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>的主题。</p><p>缓存换计算：不存 \\(y\\) 就要在反向再算一次正向局部量。激活省内存的重计算策略属于工程，本课只要求：规则里出现的 \\(\\sigma&#39;(y)\\) 必须在反向时刻能得到。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入正向模式自动微分，不写注意力的反向（注意力还没定义）。下一课<a href="/llm/autograd-two-modes">自动微分的正向与反向模式</a>比较两种扫图方式的复杂度。后课默认：线性层与逐元素激活的梯度形状与正向张量对齐，按本课三步写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性层反向是两次 GEMM：\\(\\mathrm{d}X=\\mathrm{d}Y\\,W\\)，\\(\\mathrm{d}W=\\mathrm{d}Y^\\top X\\)。</li><li>逐元素激活反向是 \\(\\odot\\sigma&#39;(y)\\)，必须能拿到 \\(y\\)。</li><li>批与序列维对 \\(\\mathrm{d}W\\) 求和，因为权重共享。</li><li>反向不是正向的逆映射，转置由配对本决定。</li><li>出处：Rumelhart et al., 1986；Goodfellow et al., Deep Learning, 2016。</li></ul>',7))])}const W=l(n,[["render",E]]);export{D as __pageData,W as default};
